program Sum;
{$mode objfpc}{$H+}
var
  I, S: Integer;
begin
  S := 0;
  for I := 1 to 100 do
    S := S + I;
  WriteLn(S);
end.

program Hello;
{$mode objfpc}{$H+}
begin
  WriteLn('Hello, World!');
end.

program Count;
{$mode objfpc}{$H+}
var
  I: Integer;
begin
  for I := 1 to 5 do
    WriteLn(I);
end.

program Largest;
{$mode objfpc}{$H+}
uses
  Math;
begin
  WriteLn(Max(Max(3, 17), 8));
end.

program Square;
{$mode delphi}
begin
  WriteLn(12 * 12);
end.

program Upper;
{$mode delphi}
uses
  SysUtils;
begin
  WriteLn(UpperCase('pascal'));
end.

program Even;
{$mode delphi}
var
  I: Integer;
begin
  I := 2;
  Write(I);
  while I < 10 do
  begin
    I := I + 2;
    Write(' ', I);
  end;
  WriteLn;
end.

program Hello;
{$mode unleashed}
begin
  WriteLn('Hello from Unleashed');
end.

program Cube;
{$mode unleashed}
begin
  var N := 4;
  WriteLn(N * N * N);
end.

program Hello;
{$APPTYPE CONSOLE}
begin
  WriteLn('Hello, Delphi');
end.

program Len;
{$APPTYPE CONSOLE}
begin
  WriteLn(Length('abcdef'));
end.
